import React, {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
} from 'react';

import {Box, Flex, Text, useThemeType} from '@gravity-ui/uikit';
import YagrComponent from '@gravity-ui/yagr/react';
import type Yagr from '@gravity-ui/yagr';

import styles from './CpuLoadChart.module.css';

const DAY_MS = 24 * 60 * 60 * 1000;
const POINT_INTERVAL_MS = 1000;
const MAX_POINTS = Math.round(DAY_MS / POINT_INTERVAL_MS);
const UPDATE_INTERVAL_MS = 1000;
const UPDATE_BATCH_SIZE = 5;

interface CpuLoadChartProps {
  className?: string;
}

function createBuffer() {
  const end = Date.now();
  const start = end - DAY_MS;
  const timeline = Array.from(
    {length: MAX_POINTS},
    (_, index) => start + index * POINT_INTERVAL_MS,
  );
  let previousValue = 18;
  const data = timeline.map((timestamp, index) => {
    const wave =
      Math.sin(index / 900) * 12 +
      Math.sin(timestamp / (5 * 60 * 1000)) * 7 +
      Math.random() * 4;
    const drift = (Math.random() - 0.48) * 2;

    previousValue = Math.min(96, Math.max(2, 26 + wave + drift + previousValue * 0.06));
    return Math.round(previousValue * 100) / 100;
  });

  return {timeline, data};
}

export function CpuLoadChart({className}: CpuLoadChartProps) {
  const reactId = useId();
  const chartId = `cpu-load-${reactId.replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const theme = useThemeType();
  const buffer = useRef(createBuffer());
  const pendingUpdates = useRef<{timeline: number[]; data: number[]}>({
    timeline: [],
    data: [],
  });
  const chartRef = useRef<Yagr | null>(null);

  const config = useMemo(() => {
    const {timeline, data} = buffer.current;

    return {
      timeline,
      chart: {
        series: {type: 'line' as const},
        appearance: {
          theme: 'light' as const,
        },
        size: {
          adaptive: true,
          resizeDebounceMs: 100,
        },
      },
      legend: {
        show: false,
      },
      cursor: {
        hideOnMouseleave: true,
      },
      scales: {
        percent: {
          min: 0,
          max: 100,
        },
      },
      series: [
        {
          id: 'cpu',
          name: 'CPU',
          color: 'var(--g-color-base-info)',
          data,
          scale: 'percent',
        },
      ],
      axes: {
        x: {},
        percent: {
          scale: 'percent',
          precision: 0,
          suffix: '%',
        },
      },
    };
  }, []);

  const handleChartInit = useCallback((chart: Yagr) => {
    chartRef.current = chart;
    chart.setTheme(buffer.current.theme);
  }, []);

  useEffect(() => {
    return () => {
      chartRef.current?.dispose();
      chartRef.current = null;
    };
  }, []);

  useEffect(() => {
    const applyUpdates = () => {
      const pending = pendingUpdates.current;
      const chart = chartRef.current;

      if (!pending.timeline.length || !chart) {
        return;
      }

      const now = Date.now();
      const expiredCount = buffer.current.timeline.filter(
        (timestamp) => timestamp < now - DAY_MS,
      ).length;
      const droppedCount = Math.min(expiredCount, pending.timeline.length);

      if (droppedCount > 0) {
        buffer.current.timeline.splice(0, droppedCount);
        buffer.current.data.splice(0, droppedCount);
      }

      buffer.current.timeline.push(...pending.timeline);
      buffer.current.data.push(...pending.data);

      chart.setSeries(
        pending.timeline,
        [{id: 'cpu', data: pending.data}],
        {incremental: true, splice: false},
      );

      pending.timeline = [];
      pending.data = [];
    };

    const intervalId = window.setInterval(applyUpdates, UPDATE_INTERVAL_MS);

    return () => {
      window.clearInterval(intervalId);
      applyUpdates();
    };
  }, []);

  useEffect(() => {
    const producer = window.setInterval(() => {
      const pending = pendingUpdates.current;
      const lastTimestamp = pending.timeline.at(-1) ?? Date.now();
      const previousValue =
        pending.data.at(-1) ??
        buffer.current.data.at(-1) ??
        20;
      const wave = Math.sin(lastTimestamp / (5 * 60 * 1000)) * 7;
      const nextValue = Math.min(
        96,
        Math.max(2, previousValue + wave * 0.08 + (Math.random() - 0.45) * 3),
      );

      pending.timeline.push(lastTimestamp + POINT_INTERVAL_MS);
      pending.data.push(Math.round(nextValue * 100) / 100);

    <Box className={className} spacing={{p: 4}}>
      <Text variant="header-2">Мониторинг</Text>
      <Flex gap={3} direction="column">
        <Text color="secondary">Загрузка CPU за последние сутки</Text>
        <Box className={styles.chartContainer}>
          <YagrComponent
            id={chartId}
            className={styles.chart}
            config={config}
            onChartInited={handleChartInit}
          />
        </Box>
      </Flex>
    </Box>
  );
}

